/* ===== GreenBean Coffee Design System ===== */
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&family=Inter:ital,opsz,wght@0,14..32,100..900;1,14..32,100..900&family=Playfair+Display:ital,wght@0,400..900;1,400..900&display=swap');

:root {
  /* Brand colors */
  --green: #00824A;
  --green-dark: #32462F;
  --green-light: #D4E9E2;
  --cream: #F3CEA1;
  --cream-light: #FFF8F0;
  --brown: #6B4E3D;
  --brown-dark: #3C2A1E;

  /* Semantic tokens */
  --primary: var(--green);
  --primary-hover: #006B3D;
  --primary-dark: var(--green-dark);
  --primary-light: var(--green-light);
  --accent: var(--cream);
  --accent-light: var(--cream-light);

  --background: #FFFDF9;
  --surface: #FFFFFF;
  --surface-hover: #F9F7F2;
  --foreground: #1A1D1B;
  --muted: #6B7280;
  --muted-light: #9CA3AF;
  --border: #E5E7E0;
  --border-light: #F0F1EB;

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-heading: 'DM Sans', 'Inter', system-ui, sans-serif;
  --font-display: 'Playfair Display', Georgia, serif;

  /* Spacing scale */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Radii */
  --radius-sm: 0.5rem;
  --radius: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-xs: 0 1px 2px rgba(50, 70, 47, 0.05);
  --shadow-sm: 0 1px 3px rgba(50, 70, 47, 0.08), 0 1px 2px rgba(50, 70, 47, 0.06);
  --shadow: 0 4px 6px rgba(50, 70, 47, 0.06), 0 2px 4px rgba(50, 70, 47, 0.04);
  --shadow-md: 0 10px 15px rgba(50, 70, 47, 0.08), 0 4px 6px rgba(50, 70, 47, 0.04);
  --shadow-lg: 0 20px 40px rgba(50, 70, 47, 0.1), 0 8px 16px rgba(50, 70, 47, 0.05);
  --shadow-xl: 0 25px 50px rgba(50, 70, 47, 0.12);

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --duration-fast: 150ms;
  --duration: 200ms;
  --duration-slow: 350ms;
  --duration-slower: 500ms;
}

/* ===== Reset & Base ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  background: var(--background);
  color: var(--foreground);
  line-height: 1.6;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
}

ul { list-style: none; }

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.display {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: -0.03em;
}

/* ===== Utility Classes ===== */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-xl);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 0.75rem 1.75rem;
  font-size: 0.938rem;
  font-weight: 600;
  font-family: var(--font-sans);
  border-radius: var(--radius-full);
  transition: all var(--duration) var(--ease-out);
  white-space: nowrap;
  letter-spacing: -0.01em;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
}
.btn-primary:hover {
  background: var(--primary-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: transparent;
  color: var(--primary);
  border: 1.5px solid var(--primary);
}
.btn-secondary:hover {
  background: var(--primary-light);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--foreground);
}
.btn-ghost:hover {
  background: var(--surface-hover);
}

.btn-cream {
  background: var(--cream);
  color: var(--brown-dark);
  font-weight: 700;
}
.btn-cream:hover {
  background: #E8BE8A;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-white {
  background: #fff;
  color: var(--foreground);
}
.btn-white:hover {
  background: #f5f5f5;
  transform: translateY(-1px);
  box-shadow: var(--shadow);
}

.btn-lg {
  padding: 1rem 2.25rem;
  font-size: 1.063rem;
}

/* ===== Header ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255, 253, 249, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 4rem;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-xl);
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 1.375rem;
  color: var(--primary-dark);
  letter-spacing: -0.03em;
}

.header-logo svg {
  width: 2rem;
  height: 2rem;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
}

.header-nav a {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--foreground);
  padding: 0.375rem 0;
  border-bottom: 2px solid transparent;
  transition: all var(--duration) var(--ease-out);
}

.header-nav a:hover,
.header-nav a.active {
  color: var(--primary);
  border-bottom-color: var(--primary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.header-actions .btn {
  padding: 0.5rem 1.25rem;
  font-size: 0.813rem;
}

.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  cursor: pointer;
}

.mobile-menu-btn span {
  width: 22px;
  height: 2px;
  background: var(--foreground);
  border-radius: 2px;
  transition: all var(--duration) var(--ease-out);
}

.mobile-menu {
  display: none;
  position: fixed;
  top: 4rem;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--background);
  padding: var(--space-xl);
  flex-direction: column;
  gap: var(--space-sm);
  z-index: 99;
  overflow-y: auto;
}

.mobile-menu.active {
  display: flex;
}

.mobile-menu a {
  display: block;
  padding: var(--space-md);
  font-size: 1.063rem;
  font-weight: 600;
  border-radius: var(--radius);
  transition: background var(--duration) var(--ease-out);
}

.mobile-menu a:hover {
  background: var(--surface-hover);
}

.mobile-menu .btn {
  margin-top: var(--space-md);
  width: 100%;
}

/* ===== Cookie Banner ===== */
.cookie-banner {
  position: fixed;
  bottom: var(--space-xl);
  left: 50%;
  transform: translateX(-50%);
  z-index: 200;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: var(--space-lg) var(--space-xl);
  max-width: 600px;
  width: calc(100% - 2rem);
  display: flex;
  align-items: flex-start;
  gap: var(--space-lg);
  animation: cookieSlideUp 0.5s var(--ease-out);
}

.cookie-banner.hidden {
  display: none;
}

.cookie-icon {
  font-size: 1.5rem;
  flex-shrink: 0;
}

.cookie-content h3 {
  font-size: 0.938rem;
  margin-bottom: var(--space-xs);
}

.cookie-content p {
  font-size: 0.813rem;
  color: var(--muted);
  line-height: 1.5;
}

.cookie-actions {
  display: flex;
  gap: var(--space-sm);
  margin-top: var(--space-md);
  flex-shrink: 0;
}

@keyframes cookieSlideUp {
  from { opacity: 0; transform: translateX(-50%) translateY(20px); }
  to { opacity: 1; transform: translateX(-50%) translateY(0); }
}

/* ===== Footer ===== */
.footer {
  background: var(--primary-dark);
  color: #D4D9D2;
  padding: var(--space-4xl) 0 var(--space-3xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-2xl);
}

.footer-col h4 {
  color: #fff;
  font-size: 0.875rem;
  font-weight: 700;
  margin-bottom: var(--space-lg);
  letter-spacing: -0.01em;
  cursor: default;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer-col a {
  font-size: 0.813rem;
  color: #A8B0A5;
  transition: color var(--duration) var(--ease-out);
}

.footer-col a:hover {
  color: #fff;
}

.footer-bottom {
  margin-top: var(--space-3xl);
  padding-top: var(--space-xl);
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-social {
  display: flex;
  gap: var(--space-md);
}

.footer-social a {
  color: #A8B0A5;
  transition: color var(--duration) var(--ease-out);
}

.footer-social a:hover {
  color: #fff;
}

.footer-legal {
  font-size: 0.75rem;
  color: #7A8076;
}

.footer-legal a {
  color: #A8B0A5;
  margin-left: var(--space-lg);
}

.footer-legal a:hover {
  color: #fff;
}

/* ===== Section Styles ===== */
.section {
  padding: var(--space-4xl) 0;
}

.section-sm {
  padding: var(--space-3xl) 0;
}

.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  margin-bottom: var(--space-md);
}

.section-title {
  font-size: 2.5rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-md);
}

.section-body {
  font-size: 1.063rem;
  color: var(--muted);
  max-width: 36rem;
  line-height: 1.7;
  margin-bottom: var(--space-xl);
}

/* ===== Hero ===== */
.hero {
  padding: var(--space-4xl) 0 var(--space-3xl);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--cream-light) 0%, #E8F5EE 50%, #F0EBE3 100%);
  z-index: -1;
}

.hero-bg::after {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(0,130,74,0.06) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-bg::before {
  content: '';
  position: absolute;
  bottom: -30%;
  left: -10%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(243,206,161,0.3) 0%, transparent 70%);
  border-radius: 50%;
}

.hero h1 {
  font-size: 4rem;
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1.05;
  color: var(--primary-dark);
  margin-bottom: var(--space-lg);
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
  font-family: var(--font-display);
}

.hero .btn {
  font-size: 1.063rem;
  padding: 1rem 2.5rem;
}

/* ===== Promo Cards ===== */
.promo-section {
  padding: var(--space-3xl) 0;
}

.promo-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
  background: var(--surface);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--duration-slow) var(--ease-out);
}

.promo-card:hover {
  box-shadow: var(--shadow-md);
}

.promo-card.reversed {
  direction: rtl;
}

.promo-card.reversed > * {
  direction: ltr;
}

.promo-image {
  width: 100%;
  height: 400px;
  object-fit: cover;
  background: var(--border-light);
}

.promo-content {
  padding: var(--space-3xl);
}

.promo-content .section-label {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  margin-bottom: var(--space-md);
}

.promo-content h2 {
  font-size: 2.25rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-md);
  color: var(--foreground);
}

.promo-content p {
  font-size: 1.063rem;
  color: var(--muted);
  line-height: 1.7;
  margin-bottom: var(--space-xl);
}

/* ===== AI Recommendation ===== */
.ai-card {
  background: linear-gradient(135deg, #1A1D1B 0%, #32462F 100%);
  border-radius: var(--radius-xl);
  padding: var(--space-3xl);
  color: #fff;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.ai-card::after {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(0,130,74,0.3) 0%, transparent 70%);
  border-radius: 50%;
}

.ai-card > * {
  position: relative;
  z-index: 1;
}

.ai-card h2 {
  font-size: 2rem;
  color: #fff;
  margin-bottom: var(--space-md);
}

.ai-card p {
  color: #B0B8AD;
  max-width: 480px;
  margin: 0 auto var(--space-xl);
}

/* ===== Menu Page ===== */
.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-2xl);
  align-items: start;
}

.menu-sidebar {
  position: sticky;
  top: 5rem;
  padding: var(--space-xl) 0;
}

.menu-sidebar h3 {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted-light);
  margin-bottom: var(--space-md);
  padding: 0 var(--space-md);
}

.menu-sidebar-nav {
  display: flex;
  flex-direction: column;
}

.menu-sidebar-nav a {
  display: block;
  padding: 0.625rem var(--space-md);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--foreground);
  border-radius: var(--radius-sm);
  transition: all var(--duration-fast) var(--ease-out);
  border-left: 3px solid transparent;
}

.menu-sidebar-nav a:hover,
.menu-sidebar-nav a.active {
  background: var(--surface-hover);
  color: var(--primary);
  border-left-color: var(--primary);
}

.menu-subnav {
  padding-left: var(--space-md);
}

.menu-subnav a {
  font-size: 0.813rem;
  font-weight: 400;
  color: var(--muted);
  padding: 0.375rem var(--space-md);
}

.menu-content {
  padding: var(--space-xl) 0;
}

.menu-section {
  margin-bottom: var(--space-3xl);
}

.menu-section-header {
  margin-bottom: var(--space-xl);
}

.menu-section-header h2 {
  font-size: 1.75rem;
  font-weight: 800;
  margin-bottom: var(--space-xs);
}

.menu-section-header p {
  color: var(--muted);
  font-size: 0.938rem;
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: var(--space-xl);
}

.menu-item {
  background: var(--surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-xs);
  border: 1px solid var(--border-light);
  transition: all var(--duration) var(--ease-out);
  cursor: pointer;
}

.menu-item:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.menu-item-image {
  width: 100%;
  height: 180px;
  object-fit: cover;
  background: var(--border-light);
}

.menu-item-body {
  padding: var(--space-lg);
}

.menu-item-body h3 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.menu-item-body p {
  font-size: 0.813rem;
  color: var(--muted);
  margin-bottom: var(--space-sm);
}

.menu-item-body .price {
  font-weight: 700;
  color: var(--primary);
  font-size: 0.938rem;
}

/* Breadcrumb */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: 0.813rem;
  color: var(--muted);
  padding: var(--space-lg) 0 0;
}

.breadcrumb a {
  color: var(--primary);
  font-weight: 500;
}

.breadcrumb a:hover {
  text-decoration: underline;
}

/* ===== Rewards Page ===== */
.rewards-hero {
  padding: var(--space-4xl) 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.rewards-hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #FFF8F0 0%, #E8F5EE 50%, #F5F0E8 100%);
  z-index: -1;
}

.rewards-hero h1 {
  font-size: 3.5rem;
  font-weight: 800;
  color: var(--primary-dark);
  margin-bottom: var(--space-md);
}

.rewards-hero p {
  font-size: 1.125rem;
  color: var(--muted);
  max-width: 560px;
  margin: 0 auto var(--space-xl);
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-2xl);
  text-align: center;
}

.step-card {
  padding: var(--space-2xl);
}

.step-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 3.5rem;
  height: 3.5rem;
  border-radius: 50%;
  background: var(--primary-light);
  color: var(--primary);
  font-size: 1.25rem;
  font-weight: 800;
  margin-bottom: var(--space-lg);
}

.step-card h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-sm);
}

.step-card p {
  color: var(--muted);
  font-size: 0.938rem;
  line-height: 1.6;
}

/* Tier Cards */
.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.tier-card {
  background: var(--surface);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  text-align: center;
  border: 2px solid var(--border);
  transition: all var(--duration-slow) var(--ease-out);
  position: relative;
}

.tier-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.tier-card.featured {
  border-color: var(--cream);
  background: linear-gradient(180deg, var(--cream-light) 0%, var(--surface) 40%);
}

.tier-badge {
  display: inline-block;
  padding: 0.25rem 1rem;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-lg);
}

.tier-badge.green { background: var(--primary-light); color: var(--primary); }
.tier-badge.gold { background: #FFF3D6; color: #A67C00; }
.tier-badge.reserve { background: #1A1D1B; color: #D4AF37; }

.tier-stars {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--foreground);
  margin-bottom: var(--space-xs);
}

.tier-threshold {
  font-size: 0.875rem;
  color: var(--muted);
  margin-bottom: var(--space-xl);
}

.tier-benefits {
  list-style: none;
  text-align: left;
}

.tier-benefits li {
  padding: 0.5rem 0;
  font-size: 0.875rem;
  color: var(--muted);
  border-bottom: 1px solid var(--border-light);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.tier-benefits li::before {
  content: '✓';
  color: var(--primary);
  font-weight: 700;
  font-size: 0.75rem;
}

/* Redemption Tabs */
.redemption-tabs {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
  margin-bottom: var(--space-2xl);
  justify-content: center;
