:root {
  /* Brand colors */
  --green: #00824A;
  --green-dark: #32462F;
  --green-light: #D4E9E2;
  --cream: #F3CEA1;
  --cream-light: #FFF8F0;
  --brown: #6B4E3D;
  --brown-dark: #3C2A1E;

  /* Semantic tokens */
  --primary: var(--green);
  --primary-hover: #006B3D;
  --primary-dark: var(--green-dark);
  --primary-light: var(--green-light);
  --accent: var(--cream);
  --accent-light: var(--cream-light);

  --background: #FFFDF9;
  --surface: #FFFFFF;
  --surface-hover: #F9F7F2;
  --foreground: #1A1D1B;
  --muted: #6B7280;
  --muted-light: #9CA3AF;
  --border: #E5E7E0;
  --border-light: #F0F1EB;

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-heading: 'DM Sans', 'Inter', system-ui, sans-serif;
  --font-display: 'Playfair Display', Georgia, serif;

  /* Spacing scale */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Radii */
  --radius-sm: 0.5rem;
  --radius: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-xs: 0 1px 2px rgba(50, 70, 47, 0.05);
  --shadow-sm: 0 1px 3px rgba(50, 70, 47, 0.08), 0 1px 2px rgba(50, 70, 47, 0.06);
  --shadow: 0 4px 6px rgba(50, 70, 47, 0.06), 0 2px 4px rgba(50, 70, 47, 0.04);
  --shadow-md: 0 10px 15px rgba(50, 70, 47, 0.08), 0 4px 6px rgba(50, 70, 47, 0.04);
  --shadow-lg: 0 20px 40px rgba(50, 70, 47, 0.1), 0 8px 16px rgba(50, 70, 47, 0.05);
  --shadow-xl: 0 25px 50px rgba(50, 70, 47, 0.12);

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --duration-fast: 150ms;
  --duration: 200ms;
  --duration-slow: 350ms;
  --duration-slower: 500ms;
}

/* ===== Reset & Base ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  background: var(--background);
  color: var(--foreground);
  line-height: 1.6;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
}

ul { list-style: none; }

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.display {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: -0.03em;
}

/* ===== Utility Classes ===== */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-xl);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 0.75rem 1.75rem;
  font-size: 0.938rem;
  font-weight: 600;
  font-family: var(--font-sans);
  border-radius: var(--radius-full);
  transition: all var(--duration) var(--ease-out);
  white-space: nowrap;
  letter-spacing: -0.01em;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
}
.btn-primary:hover {
  background: var(--primary-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: transparent;
  color: var(--primary);
  border: 1.5px solid var(--primary);
}
.btn-secondary:hover {
  background: var(--primary-light);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--foreground);
}
.btn-ghost:hover {
  background: var(--surface-hover);
}

.btn-cream {
  background: var(--cream);
  color: var(--brown-dark);
  font-weight: 700;
}
.btn-cream:hover {
  background: #E8BE8A;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-white {
  background: #fff;
  color: var(--foreground);
}
.btn-white:hover {
  background: #f5f5f5;
  transform: translateY(-1px);
  box-shadow: var(--shadow);
}

.btn-lg {
  padding: 1rem 2.25rem;
  font-size: 1.063rem;
}

/* ===== Header ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255, 253, 249, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 4rem;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-xl);
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 1.375rem;
  color: var(--primary-dark);
  letter-spacing: -0.03em;
}

.header-logo svg {
  width: 2rem;
  height: 2rem;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
}

.header-nav a {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--foreground);
  padding: 0.375rem 0;
  border-bottom: 2px solid transparent;
  transition: all var(--duration) var(--ease-out);
}

.header-nav a:hover,
.header-nav a.active {
  color: var(--primary);
  border-bottom-color: var(--primary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

.header-actions .btn {
  padding: 0.5rem 1.25rem;
  font-size: 0.813rem;
}

.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  cursor: pointer;
}

.mobile-menu-btn span {
  width: 22px;
  height: 2px;
  background: var(--foreground);
  border-radius: 2px;
  transition: all var(--duration) var(--ease-out);
}

.mobile-menu {
  display: none;
  position: fixed;
  top: 4rem;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--background);
  padding: var(--space-xl);
  flex-direction: column;
  gap: var(--space-sm);
  z-index: 99;
  overflow-y: auto;
}

.mobile-menu.active {
  display: flex;
}

.mobile-menu a {
  display: block;
  padding: var(--space-md);
  font-size: 1.063rem;
  font-weight: 600;
  border-radius: var(--radius);
  transition: background var(--duration) var(--ease-out);
}

.mobile-menu a:hover {
  background: var(--surface-hover);
}

.mobile-menu .btn {
  margin-top: var(--space-md);
  width: 100%;
}

/* ===== Cookie Banner ===== */
.cookie-banner {
  position: fixed;
  bottom: var(--space-xl);
  left: 50%;
  transform: translateX(-50%);
  z-index: 200;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: var(--space-lg) var(--space-xl);
  max-width: 600px;
  width: calc(100% - 2rem);
  display: flex;
  align-items: flex-start;
  gap: var(--space-lg);
  animation: cookieSlideUp 0.5s var(--ease-out);
}

.cookie-banner.hidden {
  display: none;
}

.cookie-icon {
  font-size: 1.5rem;
  flex-shrink: 0;
}

.cookie-content h3 {
  font-size: 0.938rem;
  margin-bottom: var(--space-xs);
}

.cookie-content p {
  font-size: 0.813rem;
  color: var(--muted);
  line-height: 1.5;
}

.cookie-actions {
  display: flex;
  gap: var(--space-sm);
  margin-top: var(--space-md);
  flex-shrink: 0;
}

@keyframes cookieSlideUp {
  from { opacity: 0; transform: translateX(-50%) translateY(20px); }
  to { opacity: 1; transform: translateX(-50%) translateY(0); }
}

/* ===== Footer ===== */
.footer {
  background: var(--primary-dark);
  color: #D4D9D2;
  padding: var(--space-4xl) 0 var(--space-3xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-2xl);
}

.footer-col h4 {
  color: #fff;
  font-size: 0.875rem;
  font-weight: 700;
  margin-bottom: var(--space-lg);
  letter-spacing: -0.01em;
  cursor: default;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer-col a {
  font-size: 0.813rem;
  color: #A8B0A5;
  transition: color var(--duration) var(--ease-out);
}

.footer-col a:hover {
  color: #fff;
}

.footer-bottom {
  margin-top: var(--space-3xl);
  padding-top: var(--space-xl);
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-social {
  display: flex;
  gap: var(--space-md);
}

.footer-social a {
  color: #A8B0A5;
  transition: color var(--duration) var(--ease-out);
}

.footer-social a:hover {
  color: #fff;
}

.footer-legal {
  font-size: 0.75rem;
  color: #7A8076;
}

.footer-legal a {
  color: #A8B0A5;
  margin-left: var(--space-lg);
}

.footer-legal a:hover {
  color: #fff;
}

/* ===== Section Styles ===== */
.section {
  padding: var(--space-4xl) 0;
}

.section-sm {
  padding: var(--space-3xl) 0;
}

.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  margin-bottom: var(--space-md);
}

.section-title {
  font-size: 2.5rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-md);
}

.section-body {
  font-size: 1.063rem;
  color: var(--muted);
  max-width: 36rem;
  line-height: 1.7;
  margin-bottom: var(--space-xl);
}

/* ===== Hero ===== */
.hero {
  padding: var(--space-4xl) 0 var(--space-3xl);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--cream-light) 0%, #E8F5EE 50%, #F0EBE3 100%);
  z-index: -1;
}

.hero-bg::after {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(0,130,74,0.06) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-bg::before {
  content: '';
  position: absolute;
  bottom: -30%;
  left: -10%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(243,206,161,0.3) 0%, transparent 70%);
  border-radius: 50%;
}

.hero h1 {
  font-size: 4rem;
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1.05;
  color: var(--primary-dark);
  margin-bottom: var(--space-lg);
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
  font-family: var(--font-display);
}

.hero .btn {
  font-size: 1.063rem;
  padding: 1rem 2.5rem;
}

/* ===== Promo Cards ===== */
.promo-section {
  padding: var(--space-3xl) 0;
}

.promo-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
  background: var(--surface);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--duration-slow) var(--ease-out);
}

.promo-card:hover {
  box-shadow: var(--shadow-md);
}

.promo-card.reversed {
  direction: rtl;
}

.promo-card.reversed > * {
  direction: ltr;
}

.promo-image {
  width: 100%;
  height: 400px;
  object-fit: cover;
  background: var(--border-light);
}

.promo-content {
  padding: var(--space-3xl);
}

.promo-content .section-label {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  margin-bottom: var(--space-md);
}

.promo-content h2 {
  font-size: 2.25rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-md);
  color: var(--foreground);
}

.promo-content p {
  font-size: 1.063rem;
  color: var(--muted);
  line-height: 1.7;
  margin-bottom: var(--space-xl);
}

/* ===== AI Recommendation ===== */
.ai-card {
  background: linear-gradient(135deg, #1A1D1B 0%, #32462F 100%);
  border-radius: var(--radius-xl);
  padding: var(--space-3xl);
  color: #fff;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.ai-card::after {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(0,130,74,0.3) 0%, transparent 70%);
  border-radius: 50%;
}

.ai-card > * {
  position: relative;
  z-index: 1;
}

.ai-card h2 {
  font-size: 2rem;
  color: #fff;
  margin-bottom: var(--space-md);
}

.ai-card p {
  color: #B0B8AD;
  max-width: 480px;
  margin: 0 auto var(--space-xl);
}

/* ===== Menu Page ===== */
.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-2xl);
  align-items: start;
}

.menu-sidebar {
  position: sticky;
  top: 5rem;
  padding: var(--space-xl) 0;
}

.menu-sidebar h3 {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted-light);
  margin-bottom: var(--space-md);
  padding: 0 var(--space-md);
}

.menu-sidebar-nav {
  display: flex;
  flex-direction: column;
}

.menu-sidebar-nav a {
  display: block;
  padding: 0.625rem var(--space-md);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--foreground);
  border-radius: var(--radius-sm);
  transition: all var(--duration-fast) var(--ease-out);
  border-left: 3px solid transparent;
}

.menu-sidebar-nav a:hover,
.menu-sidebar-nav a.active {
  background: var(--surface-hover);
  color: var(--primary);
  border-left-color: var(--primary);
}

.menu-subnav {
  padding-left: var(--space-md);
}

.menu-subnav a {
  font-size: 0.813rem;
  font-weight: 400;
  color: var(--muted);
  padding: 0.375rem var(--space-md);
}

.menu-content {
  padding: var(--space-xl) 0;
}

.menu-section {
  margin-bottom: var(--space-3xl);
}

.menu-section-header {
  margin-bottom: var(--space-xl);
}

.menu-section-header h2 {
  font-size: 1.75rem;
  font-weight: 800;
  margin-bottom: var(--space-xs);
}

.menu-section-header p {
  color: var(--muted);
  font-size: 0.938rem;
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: var(--space-xl);
}

.menu-item {
  background: var(--surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-xs);
  border: 1px solid var(--border-light);
  transition: all var(--duration) var(--ease-out);
  cursor: pointer;
}

.menu-item:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.menu-item-image {
  width: 100%;
  height: 180px;
  object-fit: cover;
  background: var(--border-light);
}

.menu-item-body {
  padding: var(--space-lg);
}

.menu-item-body h3 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.menu-item-body p {
  font-size: 0.813rem;
  color: var(--muted);
  margin-bottom: var(--space-sm);
}

.menu-item-body .price {
  font-weight: 700;
  color: var(--primary);
  font-size: 0.938rem;
}

/* Breadcrumb */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: 0.813rem;
  color: var(--muted);
  padding: var(--space-lg) 0 0;
}

.breadcrumb a {
  color: var(--primary);
  font-weight: 500;
}

.breadcrumb a:hover {
  text-decoration: underline;
}

/* ===== Rewards Page ===== */
.rewards-hero {
  padding: var(--space-4xl) 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.rewards-hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #FFF8F0 0%, #E8F5EE 50%, #F5F0E8 100%);
  z-index: -1;
}

.rewards-hero h1 {
  font-size: 3.5rem;
  font-weight: 800;
  color: var(--primary-dark);
  margin-bottom: var(--space-md);
}

.rewards-hero p {
  font-size: 1.125rem;
  color: var(--muted);
  max-width: 560px;
  margin: 0 auto var(--space-xl);
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-2xl);
  text-align: center;
}

.step-card {
  padding: var(--space-2xl);
}

.step-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 3.5rem;
  height: 3.5rem;
  border-radius: 50%;
  background: var(--primary-light);
  color: var(--primary);
  font-size: 1.25rem;
  font-weight: 800;
  margin-bottom: var(--space-lg);
}

.step-card h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-sm);
}

.step-card p {
  color: var(--muted);
  font-size: 0.938rem;
  line-height: 1.6;
}

/* Tier Cards */
.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.tier-card {
  background: var(--surface);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  text-align: center;
  border: 2px solid var(--border);
  transition: all var(--duration-slow) var(--ease-out);
  position: relative;
}

.tier-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.tier-card.featured {
  border-color: var(--cream);
  background: linear-gradient(180deg, var(--cream-light) 0%, var(--surface) 40%);
}

.tier-badge {
  display: inline-block;
  padding: 0.25rem 1rem;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-lg);
}

.tier-badge.green { background: var(--primary-light); color: var(--primary); }
.tier-badge.gold { background: #FFF3D6; color: #A67C00; }
.tier-badge.reserve { background: #1A1D1B; color: #D4AF37; }

.tier-stars {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--foreground);
  margin-bottom: var(--space-xs);
}

.tier-threshold {
  font-size: 0.875rem;
  color: var(--muted);
  margin-bottom: var(--space-xl);
}

.tier-benefits {
  list-style: none;
  text-align: left;
}

.tier-benefits li {
  padding: 0.5rem 0;
  font-size: 0.875rem;
  color: var(--muted);
  border-bottom: 1px solid var(--border-light);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.tier-benefits li::before {
  content: '✓';
  color: var(--primary);
  font-weight: 700;
  font-size: 0.75rem;
}

/* Redemption Tabs */
.redemption-tabs {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
  margin-bottom: var(--space-2xl);
  justify-content: center;
}

.redemption-tab {
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  background: var(--surface);
  border: 1.5px solid var(--border);
  color: var(--muted);
  transition: all var(--duration) var(--ease-out);
  cursor: pointer;
}

.redemption-tab:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.redemption-tab.active {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.redemption-panel {
  background: var(--surface);
  border-radius: var(--radius-xl);
  padding: var(--space-3xl);
  text-align: center;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-light);
  display: none;
  animation: fadeSlideIn 0.3s var(--ease-out);
}

.redemption-panel.active {
  display: block;
}

.redemption-stars {
  font-size: 3rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: var(--space-sm);
}

.redemption-reward {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.redemption-value {
  color: var(--muted);
  font-size: 1rem;
  margin-bottom: var(--space-xl);
}

@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ===== Gift Cards Page ===== */
.gift-hero {
  padding: var(--space-4xl) 0;
  text-align: center;
  position: relative;
  background: linear-gradient(135deg, #32462F 0%, #1A2D1F 100%);
  color: #fff;
}

.gift-hero h1 {
  font-size: 3.5rem;
  font-weight: 800;
  color: #fff;
  margin-bottom: var(--space-md);
}

.gift-hero p {
  font-size: 1.125rem;
  color: #B0B8AD;
  max-width: 520px;
  margin: 0 auto var(--space-xl);
}

/* Carousels */
.carousel-section {
  margin-bottom: var(--space-3xl);
}

.carousel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-xl);
}

.carousel-header h2 {
  font-size: 1.5rem;
  font-weight: 800;
}

.carousel-controls {
  display: flex;
  gap: var(--space-sm);
}

.carousel-btn {
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--foreground);
  transition: all var(--duration) var(--ease-out);
  cursor: pointer;
}

.carousel-btn:hover {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.carousel-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.carousel-btn:disabled:hover {
  background: var(--surface);
  border-color: var(--border);
  color: var(--foreground);
}

.carousel-track-wrapper {
  overflow: hidden;
  border-radius: var(--radius-lg);
}

.carousel-track {
  display: flex;
  gap: var(--space-lg);
  transition: transform 0.4s var(--ease-in-out);
}

.gift-card-item {
  flex: 0 0 calc(25% - 0.75rem);
  min-width: calc(25% - 0.75rem);
  background: var(--surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-xs);
  border: 1px solid var(--border-light);
  transition: all var(--duration) var(--ease-out);
  cursor: pointer;
}

.gift-card-item:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.gift-card-image {
  width: 100%;
  height: 200px;
  object-fit: cover;
  background: linear-gradient(135deg, var(--cream-light), var(--primary-light));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.813rem;
  font-weight: 600;
  color: var(--primary-dark);
}

.gift-card-body {
  padding: var(--space-md) var(--space-lg);
}

.gift-card-body h3 {
  font-size: 0.875rem;
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.gift-card-body p {
  font-size: 0.75rem;
  color: var(--muted);
}

/* Business Gifting */
.business-gifting {
  background: var(--cream-light);
  border-radius: var(--radius-xl);
  padding: var(--space-3xl);
  text-align: center;
  margin: var(--space-3xl) 0;
}

.business-gifting h2 {
  font-size: 2rem;
  margin-bottom: var(--space-md);
}

.business-gifting p {
  color: var(--muted);
  max-width: 520px;
  margin: 0 auto var(--space-xl);
}

/* eGift Info */
.egift-info {
  background: var(--surface);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  border: 1px solid var(--border-light);
}

.egift-info h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-md);
}

.egift-info p {
  color: var(--muted);
  font-size: 0.938rem;
  line-height: 1.7;
  margin-bottom: var(--space-md);
}

/* FAQ */
.faq-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.faq-item {
  border: 1px solid var(--border-light);
  border-radius: var(--radius);
  overflow: hidden;
}

.faq-question {
  width: 100%;
  padding: var(--space-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.938rem;
  font-weight: 600;
  text-align: left;
  transition: background var(--duration-fast) var(--ease-out);
}

.faq-question:hover {
  background: var(--surface-hover);
}

.faq-question svg {
  transition: transform var(--duration) var(--ease-out);
}

.faq-question.open svg {
  transform: rotate(180deg);
}

.faq-answer {
  padding: 0 var(--space-lg) var(--space-lg);
  font-size: 0.875rem;
  color: var(--muted);
  line-height: 1.6;
  display: none;
}

.faq-answer.open {
  display: block;
}

/* ===== Store Locator ===== */
.store-controls {
  display: flex;
  gap: var(--space-md);
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: var(--space-xl);
}

.order-type-toggle {
  display: flex;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-full);
  overflow: hidden;
}

.order-type-toggle button {
  padding: 0.625rem 1.25rem;
  font-size: 0.813rem;
  font-weight: 600;
  color: var(--muted);
  transition: all var(--duration) var(--ease-out);
}

.order-type-toggle button.active {
  background: var(--primary);
  color: #fff;
}

.store-search-wrapper {
  flex: 1;
  min-width: 280px;
  position: relative;
}

.store-search {
  width: 100%;
  padding: 0.75rem 1rem 0.75rem 2.75rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-full);
  font-size: 0.938rem;
  font-family: var(--font-sans);
  background: var(--surface);
  transition: all var(--duration) var(--ease-out);
}

.store-search:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0,130,74,0.1);
}

.store-search-icon {
  position: absolute;
  left: 1rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--muted-light);
}

.search-suggestions {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-lg);
  z-index: 50;
  display: none;
}

.search-suggestions.visible {
  display: block;
}

.search-suggestion-item {
  padding: 0.75rem 1rem;
  font-size: 0.875rem;
  cursor: pointer;
  transition: background var(--duration-fast) var(--ease-out);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.search-suggestion-item:hover {
  background: var(--surface-hover);
}

.search-suggestion-item:first-child {
  border-radius: var(--radius) var(--radius) 0 0;
}

.search-suggestion-item:last-child {
  border-radius: 0 0 var(--radius) var(--radius);
}

.filter-panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  margin-bottom: var(--space-xl);
  display: none;
  box-shadow: var(--shadow-md);
}

.filter-panel.visible {
  display: block;
  animation: fadeSlideIn 0.25s var(--ease-out);
}

.filter-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-lg);
}

.filter-group h4 {
  font-size: 0.813rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.filter-option {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 0.375rem 0;
  font-size: 0.875rem;
  cursor: pointer;
}

.filter-option input[type="checkbox"] {
  accent-color: var(--primary);
}

.map-container {
  width: 100%;
  height: 400px;
  background: var(--border-light);
  border-radius: var(--radius-xl);
  margin-bottom: var(--space-2xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--muted);
  font-size: 0.938rem;
  position: relative;
  overflow: hidden;
}

.map-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-md);
}

.map-pin {
  position: absolute;
  width: 20px;
  height: 20px;
  background: var(--primary);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  box-shadow: var(--shadow);
}

.map-pin::after {
  content: '';
  position: absolute;
  width: 8px;
  height: 8px;
  background: #fff;
  border-radius: 50%;
  top: 6px;
  left: 6px;
}

.store-results {
  display: grid;
  gap: var(--space-md);
}

.store-result-card {
  background: var(--surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-lg) var(--space-xl);
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  transition: all var(--duration) var(--ease-out);
  cursor: pointer;
}

.store-result-card:hover {
  box-shadow: var(--shadow);
  border-color: var(--border);
}

.store-result-info h3 {
  font-size: 1.063rem;
  font-weight: 700;
  margin-bottom: var(--space-xs);
}

.store-result-info p {
  font-size: 0.813rem;
  color: var(--muted);
  margin-bottom: var(--space-xs);
}

.store-result-features {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
  margin-top: var(--space-sm);
}

.store-feature-tag {
  padding: 0.25rem 0.625rem;
  background: var(--primary-light);
  color: var(--primary);
  border-radius: var(--radius-full);
  font-size: 0.688rem;
  font-weight: 600;
}

.store-result-distance {
  font-weight: 700;
  color: var(--primary);
  white-space: nowrap;
}

/* ===== Responsive Design ===== */
@media (max-width: 1024px) {
  .promo-card {
    grid-template-columns: 1fr;
  }

  .promo-image {
    height: 300px;
  }

  .promo-content {
    padding: var(--space-2xl);
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
    padding: var(--space-md) 0;
    display: flex;
    gap: var(--space-sm);
    overflow-x: auto;
    flex-wrap: nowrap;
    -webkit-overflow-scrolling: touch;
  }

  .menu-sidebar h3 {
    display: none;
  }

  .menu-sidebar-nav {
    flex-direction: row;
    gap: var(--space-xs);
  }

  .menu-sidebar-nav a {
    white-space: nowrap;
    border-left: none;
    border-bottom: 3px solid transparent;
    padding: 0.5rem 0.75rem;
  }

  .menu-sidebar-nav a:hover,
  .menu-sidebar-nav a.active {
    border-left-color: transparent;
    border-bottom-color: var(--primary);
  }

  .menu-subnav {
    display: none;
  }

  .tiers-grid {
    grid-template-columns: 1fr;
    max-width: 500px;
    margin: 0 auto;
  }

  .steps-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin: 0 auto;
  }

  .gift-card-item {
    flex: 0 0 calc(33.333% - 0.67rem);
    min-width: calc(33.333% - 0.67rem);
  }

  .hero h1 {
    font-size: 3rem;
  }

  .rewards-hero h1,
  .gift-hero h1 {
    font-size: 2.5rem;
  }

  .section-title {
    font-size: 2rem;
  }
}

@media (max-width: 768px) {
  .header-nav {
    display: none;
  }

  .mobile-menu-btn {
    display: flex;
  }

  .header-actions .btn-ghost {
    display: none;
  }

  .hero h1 {
    font-size: 2.25rem;
  }

  .rewards-hero h1,
  .gift-hero h1 {
    font-size: 2rem;
  }

  .section-title {
    font-size: 1.75rem;
  }

  .promo-content h2 {
    font-size: 1.5rem;
  }

  .promo-image {
    height: 220px;
  }

  .promo-content {
    padding: var(--space-xl);
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-col {
    border-bottom: 1px solid rgba(255,255,255,0.08);
  }

  .footer-col h4 {
    cursor: pointer;
    padding: var(--space-md) 0;
    margin-bottom: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    user-select: none;
  }

  .footer-col h4::after {
    content: '+';
    font-size: 1.25rem;
    font-weight: 400;
    transition: transform var(--duration) var(--ease-out);
  }

  .footer-col.open h4::after {
    content: '−';
  }

  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s var(--ease-out), padding 0.3s var(--ease-out);
  }

  .footer-col.open ul {
    max-height: 400px;
    padding-bottom: var(--space-lg);
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-md);
    text-align: center;
  }

  .ai-card {
    padding: var(--space-2xl);
  }

  .ai-card h2 {
    font-size: 1.5rem;
  }

  .cookie-banner {
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: var(--space-md);
  }

  .cookie-actions {
    flex-direction: column;
    width: 100%;
  }

  .cookie-actions .btn {
    width: 100%;
  }

  .gift-card-item {
    flex: 0 0 calc(50% - 0.5rem);
    min-width: calc(50% - 0.5rem);
  }

  .store-controls {
    flex-direction: column;
    align-items: stretch;
  }

  .store-result-card {
    flex-direction: column;
    gap: var(--space-sm);
  }

  .menu-grid {
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: var(--space-md);
  }

  .redemption-tabs {
    gap: var(--space-xs);
  }

  .redemption-tab {
    padding: 0.5rem 1rem;
    font-size: 0.75rem;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 var(--space-md);
  }

  .header-inner {
    padding: 0 var(--space-md);
  }

  .hero {
    padding: var(--space-3xl) 0;
  }

  .hero h1 {
    font-size: 1.75rem;
  }

  .section {
    padding: var(--space-3xl) 0;
  }

  .promo-card {
    border-radius: var(--radius);
  }

  .gift-card-item {
    flex: 0 0 calc(80% - 0.5rem);
    min-width: calc(80% - 0.5rem);
  }

  .carousel-header {
    flex-direction: column;
    gap: var(--space-md);
    align-items: flex-start;
  }

  .redemption-panel {
    padding: var(--space-xl);
  }

  .tier-card {
    padding: var(--space-xl);
  }
}
